import { useState, useEffect, useRef } from "react";
import { Chip } from "@/shared/ui/data/Chip";
import { Button } from "@/shared/ui/controls/Button";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

// PreviewPaneShell is the modular, streaming-capable REPLACEMENT for PlanPreviewPane (already vendored
// as `planpreviewpane`) — its real distinguishing feature is an IMPERATIVE renderer-registry pipeline
// (mounts a renderer directly into a DOM ref, zero React re-renders on the hot path) that has no visual
// manifestation without live streamed content; in the empty/idle state shown here it looks the same as
// PlanPreviewPane by design ("External behavior is identical" per its own header comment) — a genuine,
// expected near-duplicate, not a vendoring mistake.
//
// Multiple first-party FEATURE-level sibling cross-imports reliably fail to build in this sandbox (same
// limit ClaudeConfigCard/PlannerLibraryPane/PlanPreviewPane hit) — inlined StageScreenFrame + its
// IconButton dependency locally instead of importing.

const CLOSE_GLYPH = "✕";
function IconButton({ "aria-label": ariaLabel, onClick, children, size = "md", danger, disabled, title, className, style }) {
  return (
    <button type="button" className={["icon-btn", size !== "md" && size, danger && "danger", className].filter(Boolean).join(" ")} aria-label={ariaLabel} title={title ?? ariaLabel} onClick={onClick} disabled={disabled} style={style}>
      {children ?? CLOSE_GLYPH}
    </button>
  );
}
function StageScreenFrame({ label, badge, statusLabel, statusColor, actions, onClose, footer, fullWidth, bare, children }) {
  return (
    <section style={{
      ...(fullWidth ? { flex: 1, minWidth: 0 } : { flex: "0 0 auto", width: 420, borderLeft: "1px solid var(--border-soft)" }),
      display: "flex", flexDirection: "column", minHeight: 0, overflow: "hidden", background: "var(--bg-panel)",
    }}>
      {!bare && (
        <Row className="mono" gap={8} style={{
          padding: "10px 14px", borderBottom: "1px solid var(--border-soft)",
          fontSize: 11, color: "var(--fg-muted)",
        }}>
          <Text as="span" tone="accent">▸ {label}</Text>
          {badge}
          <Box as="span" style={{ flex: 1 }} />
          {statusLabel && <Text as="span" size={10} style={{ color: statusColor ?? "var(--fg-dim)" }}>{statusLabel}</Text>}
          {actions}
          {onClose && <IconButton aria-label="Close" onClick={onClose} />}
        </Row>
      )}
      <Stack style={{ flex: 1, minHeight: 0 }}>{children}</Stack>
      {footer}
    </section>
  );
}

// Vendored from `./claudeDesignBrief` (unresolvable in this sandbox) — pure, unchanged.
function buildClaudeDesignBrief(screens) {
  const list = screens.length ? screens.map((s) => `- **${s}**`).join("\n") : "- (no screens defined yet)";
  return `# Design brief\n\nDesign these screens as polished, production-ready UI components:\n\n${list}`;
}

// Preview-only sample state standing in for the real useAppStore slices + the imperative renderer
// registry (`getRenderer`/`RendererHandle` from ./registry) — both app-internal, unresolvable here.
const SAMPLE_DECLARED = ["Dashboard", "ProjectDetail", "Settings"];

export function PreviewPaneShell({ projectKey = "northwind", onClose }) {
  const [preview] = useState(null);
  const [stageStatus] = useState("idle");
  const [declared] = useState(SAMPLE_DECLARED);
  const [approvedList, setApprovedList] = useState(["Dashboard"]);
  const setUiScreenApproved = (pk, screen, on) => setApprovedList((a) => on ? [...a, screen] : a.filter((s) => s !== screen));
  const [rendStatus] = useState({ status: "ready" });
  const [activeKind] = useState(null);
  const [briefCopied, setBriefCopied] = useState(false);
  const containerRef = useRef(null);

  const currentScreen = preview?.screen;
  const currentApproved = !!currentScreen && approvedList.includes(currentScreen);
  const approvedCount = declared.filter((s) => approvedList.includes(s)).length;

  const renderDemo = () => {};
  const loadSkeleton = () => {};

  const frameError = rendStatus.status === "error" ? (rendStatus.message ?? "") : "";
  const statusLabel = stageStatus === "running" ? "building…" : frameError ? "error" : stageStatus;
  const statusColor =
    frameError || stageStatus === "fail" ? "var(--danger)"
    : stageStatus === "ok"               ? "var(--success)"
    : "var(--fg-dim)";

  return (
    <StageScreenFrame
      label="preview"
      badge={preview && <Chip style={{ fontSize: 9 }}>{preview.mode}</Chip>}
      statusLabel={statusLabel}
      statusColor={statusColor}
      onClose={onClose}
      actions={
        <>
          {preview && currentScreen && (
            <Button
              size="sm"
              variant={currentApproved ? "default" : "ghost"}
              onClick={() => setUiScreenApproved(projectKey, currentScreen, !currentApproved)}
              title={currentApproved ? `${currentScreen} approved — click to revoke` : `Approve ${currentScreen}`}
              style={currentApproved ? { color: "var(--success)", borderColor: "var(--success)" } : undefined}
            >
              {currentApproved ? "✓ approved" : "approve"}
            </Button>
          )}
          {preview && <Button variant="ghost" size="sm" onClick={renderDemo} title="Rebuild">↻</Button>}
        </>
      }
      footer={declared.length > 0 && (
        <Box pad={[8, 12]} style={{ borderTop: "1px solid var(--border-soft)", maxHeight: 180, overflow: "auto" }}>
          <Row gap={8} style={{ fontFamily: "var(--mono)", fontSize: 10, color: "var(--fg-muted)", marginBottom: 6 }}>
            <Text as="span">screens</Text>
            <Button
              variant="ghost"
              size="sm"
              title="Copy a Claude Design prompt for these screens"
              onClick={() => {
                void navigator.clipboard?.writeText(buildClaudeDesignBrief(declared));
                setBriefCopied(true);
                setTimeout(() => setBriefCopied(false), 1600);
              }}
            >{briefCopied ? "✓ copied" : "✦ Claude Design brief"}</Button>
            <Box as="span" style={{ flex: 1 }} />
            <Text as="span" style={{ color: approvedCount === declared.length ? "var(--success)" : "var(--fg-dim)" }}>
              {approvedCount}/{declared.length} approved
            </Text>
          </Row>
          <Stack gap={2}>
            {declared.map((s) => {
              const ok = approvedList.includes(s);
              return (
                <Button
                  key={s}
                  variant="ghost"
                  size="sm"
                  onClick={() => setUiScreenApproved(projectKey, s, !ok)}
                  title={ok ? `${s} approved — click to revoke` : `Approve ${s}`}
                  style={{ display: "flex", alignItems: "center", gap: 8, justifyContent: "flex-start", textAlign: "left", fontFamily: "var(--mono)", fontSize: 11 }}
                >
                  <Text as="span" style={{ color: ok ? "var(--success)" : "var(--fg-dim)" }}>{ok ? "✓" : "○"}</Text>
                  <Text as="span" style={{ color: s === currentScreen ? "var(--accent)" : "var(--fg)" }}>{s}</Text>
                </Button>
              );
            })}
          </Stack>
        </Box>
      )}
    >
      <Stack style={{ flex: 1, minHeight: 0 }}>
        {stageStatus === "fail" ? (
          <Box pad={16} style={{ fontFamily: "var(--mono)", fontSize: 11, color: "var(--danger)", whiteSpace: "pre-wrap", overflow: "auto" }}>
            Preview failed to build.
          </Box>
        ) : (
          <>
            {/* Persistent imperative surface — the real renderer registry mounts into this ref directly */}
            <div ref={containerRef} style={{ flex: 1, display: activeKind ? "flex" : "none", minHeight: 0 }} />
            {!activeKind && (
              <Stack gap={12} align="center" justify="center" style={{ flex: 1, padding: 24, textAlign: "center" }}>
                <Text as="div" size={11.5} tone="muted" mono>
                  {stageStatus === "running" ? "Bundling…" : "No preview yet"}
                </Text>
                <Box className="hint" style={{ maxWidth: 280 }}>
                  The UI stage renders generated screens here via the render-preview pipeline.
                </Box>
                <Row gap={8} align="stretch">
                  <Button onClick={loadSkeleton} disabled={stageStatus === "running"}>load from skeleton →</Button>
                  <Button variant="ghost" onClick={renderDemo} disabled={stageStatus === "running"}>demo</Button>
                </Row>
              </Stack>
            )}
          </>
        )}
      </Stack>
    </StageScreenFrame>
  );
}
